await db.query("insert into public.farm_billing_controls(farm_id,courtesy_enabled,courtesy_expires_on) values($1,true,public.app_today()+7) on conflict(farm_id) do update set courtesy_enabled=true,courtesy_expires_on=public.app_today()+7",[farmA]);
await as(ownerA);
let presented=(await db.query('select public.app_my_production_plan() x')).rows[0].x;
assert.equal(presented.farmName,(await db.query('select name from public.farms where id=$1',[farmA])).rows[0].name);
assert.equal(presented.courtesy.enabled,true);assert.equal(presented.courtesy.active,true);
assert.equal(presented.courtesy.expiresOn,(await db.query('select (public.app_today()+7)::text x')).rows[0].x);
assert.ok(Array.isArray(presented.orders));assert.ok('annualPurchase' in presented);
await assert.rejects(db.query('select app_private.app_my_production_plan_before_presentation()'),/permission denied/);
await db.exec('reset role');
await db.query('update public.farm_billing_controls set courtesy_expires_on=public.app_today()-1 where farm_id=$1',[farmA]);
await db.exec(presentationMigration); // Reaplicação não duplica wrappers nem perde planos.
await as(ownerA);presented=(await db.query('select public.app_my_production_plan() x')).rows[0].x;assert.equal(presented.courtesy.active,false);
await db.exec('reset role');await db.query('update public.farm_billing_controls set courtesy_expires_on=null where farm_id=$1',[farmA]);
await as(ownerA);presented=(await db.query('select public.app_my_production_plan() x')).rows[0].x;assert.equal(presented.courtesy.active,true);assert.equal(presented.courtesy.expiresOn,null);
await db.exec('reset role');await db.query('update public.farm_billing_controls set courtesy_enabled=false,courtesy_expires_on=null where farm_id=$1',[farmB]);
await as(ownerB);presented=(await db.query('select public.app_my_production_plan() x')).rows[0].x;assert.equal(presented.courtesy.enabled,false,'cortesia da fazenda A não vaza para B');
await db.exec('reset role;set role anon');await assert.rejects(db.query('select public.app_my_production_plan()'),/permission denied/);
console.log('APRESENTAÇÃO: nome, cortesia datada, expirada e sem prazo, isolamento entre fazendas, acesso privado e reaplicação validados.');
const contactMigration=fs.readFileSync(new URL('../supabase/migrations/20261018030000_signup_contact_phone.sql',import.meta.url),'utf8');
await db.exec('reset role');await db.exec(contactMigration);
await db.query("update auth.users set raw_user_meta_data=raw_user_meta_data||jsonb_build_object('phone','+5562999991234') where id=$1",[ownerB]);
await as(ownerA);let contactRows=await tenant('list_requests');assert.equal(contactRows.find(x=>x.userId===ownerB).phone,'+5562999991234');assert.equal(contactRows.find(x=>x.userId===ownerA).phone,null);
await assert.rejects(db.query("select app_private.app_tenant_before_contact_phone('list_requests','{}')"),/permission denied/);
await as(ownerB);await assert.rejects(tenant('list_requests'),/administrador/);
assert.ok((await tenant('context')).status,'outras operações de contexto preservadas');
await db.exec('reset role');await db.exec(contactMigration);await as(ownerA);assert.equal((await tenant('list_requests')).find(x=>x.userId===ownerB).phone,'+5562999991234');
await db.exec('reset role;set role anon');await assert.rejects(db.query("select public.app_tenant('list_requests','{}')"),/permission denied/);
console.log('TELEFONE: contato restrito ao admin, legado sem contato, contexto preservado e reaplicação validados.');
const tagMigration=fs.readFileSync(new URL('../supabase/migrations/20261018040000_ear_tags_per_lot.sql',import.meta.url),'utf8');
await db.exec('reset role');await db.exec(tagMigration);
await db.exec("update public.platform_billing_settings set mode='manual' where singleton");
await db.query("update public.account_access set status='approved' where user_id=$1",[ownerB]);
await db.query("update public.farms set enabled=true where id=$1",[farmB]).catch(()=>{});
await as(ownerB);
const tagPen=await rpc('save_pen',{code:'TAG-PEN',capacity_head:100,status:'vazio'});
const tagLot=(code,tags)=>({lot:{code,head_count:tags.length,entry_date:today,entry_avg_weight_kg:400,target_weight_kg:520,pen_id:tagPen},animals:tags.map(ear_tag=>({ear_tag,entry_weight_kg:400})),applyProtocol:false});
const tagA=await rpc('create_lot',tagLot('TAG-LOTE-A',['TAG-1','TAG-2']));
const blockedRequest=crypto.randomUUID();
await assert.rejects(rpc('create_lot',tagLot('TAG-LOTE-B',['TAG-1','TAG-3']),blockedRequest),/BRINCOS_OUTROS_LOTES:.*TAG-1.*TAG-LOTE-A/);
assert.equal((await db.query("select count(*)::int n from public.lots where code='TAG-LOTE-B'")).rows[0].n,0,'alerta não grava lote parcial');
const tagB=await rpc('create_lot',{...tagLot('TAG-LOTE-B',['TAG-1','TAG-3']),confirmedDuplicateEarTags:['TAG-1']},blockedRequest);
assert.notEqual(tagA.id,tagB.id);assert.equal((await db.query("select count(*)::int n from public.animals where ear_tag='TAG-1'")).rows[0].n,2);
assert.equal((await rpc('create_lot',tagLot('TAG-LOTE-B',['TAG-1','TAG-3']),blockedRequest)).id,tagB.id,'replay confirmado sem duplicar o lote');
await assert.rejects(rpc('create_lot',{...tagLot('TAG-LOTE-C',['TAG-X','TAG-X']),confirmedDuplicateEarTags:['TAG-X']}),/mesmo brinco dentro do lote/);
await assert.rejects(rpc('save_animal',{ear_tag:'TAG-1',lot_id:tagA.id,status:'ativo',entry_weight_kg:400,current_weight_kg:400,confirmedDuplicateEarTags:['TAG-1']}),/mesmo brinco dentro do lote/);
await db.exec('reset role');
await assert.rejects(db.query("insert into public.animals(farm_id,lot_id,ear_tag,status) values($1,$2,'TAG-1','ativo')",[farmB,tagA.id]),/animals_farm_lot_tag_unique/);
await db.exec(tagMigration);await as(ownerB);
const existingTag=(await db.query("select * from public.animals where lot_id=$1 and ear_tag='TAG-1'",[tagA.id])).rows[0];
await rpc('save_animal',{...existingTag,current_weight_kg:410});
await assert.rejects(db.query("select app_private.app_mutate_before_lot_tags('save_animal','{}',gen_random_uuid())"),/permission denied/);
await db.exec('reset role;set role anon');await assert.rejects(db.query("select public.app_mutate('create_lot','{}',gen_random_uuid())"),/permission denied/);
await as(ownerA);
const tagPenA=await rpc('save_pen',{code:'TAG-PEN-A',capacity_head:50,status:'vazio'});
const foreignTag=await rpc('create_lot',{...tagLot('TAG-OUTRA-FAZENDA',['TAG-1']),lot:{...tagLot('TAG-OUTRA-FAZENDA',['TAG-1']).lot,pen_id:tagPenA}});
assert.ok(foreignTag.id,'mesmo brinco em outra fazenda não exige confirmação nem é bloqueado');
await as(ownerB);
const editableTag=(await db.query("select * from public.animals where lot_id=$1 and ear_tag='TAG-2'",[tagA.id])).rows[0];
await assert.rejects(rpc('save_animal',{...editableTag,ear_tag:'TAG-3'}),/BRINCOS_OUTROS_LOTES:.*TAG-3/);
await rpc('save_animal',{...editableTag,ear_tag:'TAG-3',confirmedDuplicateEarTags:['TAG-3']});
assert.equal((await db.query("select count(*)::int n from public.animals where ear_tag='TAG-3'")).rows[0].n,2);
console.log('BRINCOS: alerta sem gravação, confirmação entre lotes, bloqueio no mesmo lote, replay, edição sem novo alerta e reaplicação validados.');
await db.close();
